/* === CEnumeration.js === */
/* quickjs-master/amiga/ffi/CEnumeration.js
 *
 * Specialization of the vendored Enumeration for C-enum bridges
 * whose `value` may be either a primitive number/string or a
 * structured record like `{cName, value, autodoc}`. Layered so the
 * vendored Enumeration class stays pure.
 *
 * Adds:
 *   - drilled `valueOf` / `[Symbol.toPrimitive]('number')` so cases
 *     coerce to their underlying numeric value either way
 *   - extended `static from(query)` that also matches against fields
 *     on a structured value object or on the associations object
 *
 * Library wrapper consts (Intuition.consts, GadTools.consts, ...)
 * all extend this, NOT the base Enumeration.
 */


/**
 * @extends Enumeration
 */
class CEnumeration extends Enumeration {
  /**
   * Drill into structured values: if `this.value` is a plain object
   * with a `.value` field, return that field. Otherwise return
   * `this.value` unchanged.
   *
   * @returns {*}
   */
  valueOf() {
    if (
      this.value !== null &&
      typeof this.value === 'object' &&
      'value' in this.value
    ) {
      return this.value.value;
    }

    return this.value;
  }

  /**
   * What a case becomes when JavaScript needs a plain value.
   *
   *   Number(c), c | 0, c & mask     its number
   *   c + 1, c == 0x200, c < 10      its number, when it has one
   *   String(c), `${c}`, obj[c]      its name
   *
   * The middle line is what makes a constant behave like the number
   * it stands for in arithmetic and in == comparisons. (Until 0.223
   * those gave the name, so `C.WA_Left + 1` was the text "WA_Left1".)
   * A case whose value is a record rather than a number, such as an
   * EventKind, still gives its name there.
   *
   * === is not affected by any of this: a case is only identical to
   * itself. Use Number(c) to compare with === against a plain number.
   *
   * @param {string} hint  'number' | 'string' | 'default'
   * @returns {number|string}
   */
  [Symbol.toPrimitive](hint) {
    if (hint === 'number') {
      let v = this.valueOf();

      return typeof v === 'number' ? v : Number(v);
    }

    if (hint === 'default' && typeof this.value === 'number') {
      return this.value;
    }

    return String(this.key);
  }

  /**
   * Look up a case by key, primitive value, or any field on a
   * structured value or association object. Returns the matching
   * case or null.
   *
   * Matching priority (first hit wins):
   *   1. base Enumeration.from(query) — key (===) and value (==)
   *   2. case.value[anyField] === query     (structured value form)
   *   3. case.associations[anyField] === query  (associated metadata)
   *
   * @param {*} query
   * @returns {CEnumeration|null}
   */
  static from(query) {
    let base = super.from(query);

    if (base) {
      return base;
    }

    for (const [, c] of this) {
      if (c.value !== null && typeof c.value === 'object') {
        for (const k in c.value) {
          if (c.value[k] === query) {
            return c;
          }
        }
      }

      if (c.associations && typeof c.associations === 'object') {
        for (const k in c.associations) {
          if (c.associations[k] === query) {
            return c;
          }
        }
      }
    }

    return null;
  }

  /**
   * Make an enumeration class from a table of names and numbers whose
   * cases are only created when they are first used.
   *
   * A wrapper such as Intuition.consts offers hundreds of constants,
   * and a script uses a handful. Creating every case when the library
   * starts cost about a third of start-up time with only 190 of them
   * (measured on 0.220), so the cases are made on demand instead:
   *
   *   const C = Intuition.consts;
   *   C.WA_Left              // the case is created here, once
   *   C.from(0x200)          // looked up in the table, then created
   *   for (let [k, v] of C)  // creates every case first
   *
   * Everything a script could do with an ordinary CEnumeration class
   * still works; only the moment of creation changes.
   *
   * @param {string} name - the class name, e.g. 'IntuitionConsts'
   * @param {Object<string, number>} table - constant name to value
   * @returns {typeof CEnumeration} a class to use like any other
   *   enumeration class
   */
  static lazy(name, table) {
    const Base = this;
    const keys = Object.keys(table);
    const own = Object.prototype.hasOwnProperty;

    /** True once every case exists. */
    let complete = false;

    /** prefix -> (value -> name), filled in by fromPrefix().
     *  @type {Map<string, Map<number, string>>} */
    const families = new Map();

    /* The braces give the class its name: a class expression takes the
     * name of the property it is assigned to. */
    const Class = ({
      [name]: class extends Base {
        /**
         * Find a case by name or by value. A value shared by several
         * constants gives the first in the table; use fromPrefix()
         * when the family is known.
         *
         * @param {string|number|*} query
         * @returns {CEnumeration|null}
         */
        static from(query) {
          if (typeof query === 'string' && own.call(table, query)) {
            return create(query);
          }

          if (typeof query === 'number') {
            for (let index = 0; index < keys.length; index++) {
              if (table[keys[index]] === query) return create(keys[index]);
            }

            return null;
          }

          createAll();
          return super.from(query);
        }

        /**
         * Find the case with this value among the constants whose
         * names start with `prefix`. Many constants share a number
         * (IDCMP_CLOSEWINDOW and WFLG_REPORTMOUSE are both 0x200), so
         * a value alone does not say which is meant.
         *
         * @param {string} prefix - e.g. 'IDCMP_'
         * @param {number} value
         * @returns {CEnumeration|null}
         */
        static fromPrefix(prefix, value) {
          /* Called for every window message, so the scan of the whole
           * table is done once per prefix and remembered. */
          let index = families.get(prefix);

          if (!index) {
            index = new Map();

            for (let position = 0; position < keys.length; position++) {
              let key = keys[position];

              if (key.startsWith(prefix) && !index.has(table[key])) {
                index.set(table[key], key);
              }
            }

            families.set(prefix, index);
          }

          let key = index.get(value);

          return key === undefined ? null : create(key);
        }
      },
    })[name];

    /**
     * Create one case if it does not exist yet, and return it.
     *
     * @param {string} key
     * @returns {CEnumeration}
     */
    function create(key) {
      if (!own.call(Class, key)) Class.define(key, table[key]);

      return Class[key];
    }

    /**
     * Create every case that does not exist yet.
     *
     * @returns {undefined}
     */
    function createAll() {
      if (complete) return;

      complete = true;
      for (let index = 0; index < keys.length; index++) create(keys[index]);
    }

    /**
     * The table name most like a misspelt one, as a hint for an error
     * message: the name sharing the longest run of leading characters,
     * and of those the one closest in length.
     *
     * @param {string} wanted
     * @returns {string} ' - did you mean X?' or ''
     */
    function nearest(wanted) {
      let best = '';
      let bestShared = 2;      /* at least three characters in common */

      for (let index = 0; index < keys.length; index++) {
        let candidate = keys[index];
        let shared = 0;

        while (shared < candidate.length && shared < wanted.length &&
               candidate[shared] === wanted[shared]) {
          shared++;
        }

        if (shared > bestShared ||
            (shared === bestShared && best &&
             Math.abs(candidate.length - wanted.length) <
             Math.abs(best.length - wanted.length))) {
          best = candidate;
          bestShared = shared;
        }
      }

      return best ? ' - did you mean ' + best + '?' : '';
    }

    /**
     * Whether a property name is shaped like an OS constant: it starts
     * with a capital and either has an underscore (WA_Left) or is all
     * capitals and digits, four or more long (JAM1, CHECKIT). Ordinary
     * property names (from, name, toJSON, then) are not.
     *
     * Written without a regular expression on purpose: see the note on
     * regular expressions in precompiled bytecode in this file's
     * history (0.221).
     *
     * @param {string} key
     * @returns {boolean}
     */
    function looksLikeConstant(key) {
      let first = key.charCodeAt(0);

      if (!(first >= 65 && first <= 90)) return false;       /* A-Z */
      if (key.indexOf('_') > 0) return true;
      if (key.length < 4) return false;

      for (let index = 1; index < key.length; index++) {
        let code = key.charCodeAt(index);
        let capital = code >= 65 && code <= 90;
        let digit   = code >= 48 && code <= 57;

        if (!capital && !digit) return false;
      }

      return true;
    }

    return new Proxy(Class, {
      get(target, key, receiver) {
        if (typeof key === 'string' && own.call(table, key)) {
          return create(key);
        }

        /* Anything that walks the cases needs them all to exist. */
        if (key === 'cases' || key === 'values' || key === Symbol.iterator) {
          createAll();
        }

        /* A name that looks like a constant but is not one is a
         * spelling mistake, and `undefined` would travel on silently
         * (in a tag list it used to END the list). Say so here, with
         * the nearest real name. To ask whether a constant exists,
         * use `'WA_Left' in Intuition.consts`. */
        if (typeof key === 'string' && !Reflect.has(target, key) &&
            looksLikeConstant(key)) {
          throw new TypeError(name + ' has no constant ' + key +
                              nearest(key));
        }

        return Reflect.get(target, key, receiver);
      },

      has(target, key) {
        return (typeof key === 'string' && own.call(table, key)) ||
               Reflect.has(target, key);
      },

      ownKeys(target) {
        createAll();
        return Reflect.ownKeys(target);
      },

      getOwnPropertyDescriptor(target, key) {
        if (typeof key === 'string' && own.call(table, key)) create(key);

        return Reflect.getOwnPropertyDescriptor(target, key);
      },
    });
  }
}


/* === ptrOf.js === */
/* quickjs-master/amiga/ffi/ptrOf.js
 *
 * Tiny helper used by every FFI wrapper method that takes pointer
 * arguments. Coerces JS values to raw 32-bit pointer numbers.
 */

/**
 * Coerce a JS value to a raw pointer (number).
 *
 * Accepts:
 *   - null / undefined          → 0
 *   - number                    → as-is (truncated to int32 via | 0)
 *   - struct instance (.ptr)    → its .ptr field
 *   - anything else             → coerced via | 0 (NaN -> 0)
 *
 * @param {*} x
 * @returns {number}
 */
function ptrOf(x) {
  if (x === null || x === undefined) {
    return 0;
  }

  if (typeof x === 'object' && typeof x.ptr === 'number') {
    return x.ptr;
  }

  return x | 0;
}


/* === LibraryBase.js === */
/* quickjs-master/amiga/ffi/LibraryBase.js
 *
 * Common base class for AmigaOS library wrappers. Subclasses:
 *   - set static libraryName, libraryVersion, lvo
 *   - add static methods that build a regs map and call this.call()
 *
 * Lifecycle: lazy open on first method call, cached. closeLibrary()
 * is idempotent; closeAll() iterates every subclass that was opened
 * and is registered as a script-exit hook.
 */

/**
 * @abstract
 */
class LibraryBase {
  /**
   * AmigaOS library node name, e.g. 'intuition.library'. Required.
   *
   * @type {string}
   */
  static libraryName = '';

  /**
   * Minimum library version (matches the second arg of OpenLibrary).
   *
   * @type {number}
   */
  static libraryVersion = 0;

  /**
   * Cached library base pointer (0 if not yet opened).
   *
   * @type {number}
   */
  static libraryBase = 0;

  /**
   * Function-vector offsets keyed by LVO name.
   *
   * @type {Object<string, number>}
   */
  static lvo = {};

  /**
   * Open the library if it isn't already; cache and return the base.
   *
   * @returns {number} library base (non-zero)
   * @throws {Error} when the library can't be opened
   */
  static ensureLibrary() {
    if (this.libraryBase) {
      return this.libraryBase;
    }

    let base = globalThis.amiga.openLibrary(
      this.libraryName,
      this.libraryVersion
    );

    if (!base) {
      throw new Error(
        'LibraryBase: could not open ' +
        this.libraryName + ' v' + this.libraryVersion
      );
    }

    this.libraryBase = base;
    LibraryBase._opened.add(this);

    return base;
  }

  /**
   * Close the library if open. Idempotent.
   *
   * @returns {undefined}
   */
  static closeLibrary() {
    if (!this.libraryBase) {
      return;
    }

    globalThis.amiga.closeLibrary(this.libraryBase);
    this.libraryBase = 0;
    LibraryBase._opened.delete(this);
  }

  /**
   * Internal — wraps amiga.call with the lazily opened base.
   *
   * @param {number} lvo
   * @param {Object} regs
   * @returns {number}
   */
  static call(lvo, regs) {
    return globalThis.amiga.call(this.ensureLibrary(), lvo, regs || {});
  }

  /**
   * Close every library opened via the wrapper layer. Registered as a
   * script-exit hook by index.js so unclean exits don't leak.
   *
   * @returns {undefined}
   */
  static closeAll() {
    for (const cls of Array.from(LibraryBase._opened)) {
      cls.closeLibrary();
    }
  }
}

/** @internal */
LibraryBase._opened = new Set();


/* === structs/Struct.js === */
/* quickjs-master/amiga/ffi/structs/Struct.js
 *
 * Base class for struct-pointer wrappers. Subclasses set a static
 * SIZE (in bytes) and add named getters/setters that read/write at
 * fixed byte offsets. Constructor allocates if no ptr given, or
 * wraps an existing ptr if one is passed.
 *
 * Memory model: explicit. Caller (or ergonomic helpers like
 * withStruct) is responsible for `.free()`.
 */

/**
 * @abstract
 */
class Struct {
  /**
   * Byte size of this struct. Subclasses MUST override.
   *
   * @type {number}
   */
  static SIZE = 0;

  /**
   * Pointer to the struct in Amiga memory. Zero if freed or wrapping
   * a null.
   *
   * @type {number}
   */
  ptr;

  /**
   * @param {number} [ptr] if given, wrap this existing pointer (no
   *   allocation, no auto-free responsibility). If omitted, allocate
   *   a fresh `SIZE`-byte buffer with MEMF_PUBLIC|MEMF_CLEAR.
   */
  constructor(ptr) {
    if (ptr !== undefined) {
      this.ptr = ptr | 0;
      this._owned = false;
      return;
    }

    let size = this.constructor.SIZE;

    if (!size) {
      throw new Error(
        'Struct subclass ' + this.constructor.name +
        ' must define a static SIZE'
      );
    }

    this.ptr = globalThis.amiga.allocMem(size);

    if (!this.ptr) {
      throw new Error(
        'Struct: allocMem(' + size + ') failed for ' +
        this.constructor.name
      );
    }

    this._owned = true;
  }

  /**
   * Release the underlying memory. Only frees memory we allocated
   * (constructor without ptr). Idempotent.
   *
   * @returns {undefined}
   */
  free() {
    if (this.ptr && this._owned) {
      globalThis.amiga.freeMem(this.ptr, this.constructor.SIZE);
    }

    this.ptr = 0;
  }

  /* --- Field-access helpers — subclasses use these in getters/setters. --- */

  read8 (off) { return globalThis.amiga.peek8 (this.ptr + off); }
  read16(off) { return globalThis.amiga.peek16(this.ptr + off); }
  read32(off) { return globalThis.amiga.peek32(this.ptr + off); }

  write8 (off, v) { globalThis.amiga.poke8 (this.ptr + off, v); }
  write16(off, v) { globalThis.amiga.poke16(this.ptr + off, v); }
  write32(off, v) { globalThis.amiga.poke32(this.ptr + off, v); }
}

/**
 * Allocate a struct, run `fn`, free it whether or not fn throws.
 *
 * @template T
 * @param {new () => T} StructClass
 * @param {(s: T) => *} fn
 * @returns {*} fn's return value
 */
function withStruct(StructClass, fn) {
  let s = new StructClass();

  try {
    return fn(s);
  }

  finally {
    s.free();
  }
}


