/* === structs/IntuiMessage.js === */
/* quickjs-master/amiga/ffi/structs/IntuiMessage.js
 *
 * struct IntuiMessage (intuition/intuition.h) layout:
 *   +0..19  struct Message (ExecMessage prefix, 20 bytes)
 *  +20  Class (ULONG)
 *  +24  Code (UWORD)
 *  +26  Qualifier (UWORD)
 *  +28  IAddress (APTR)
 *  +32  MouseX (WORD), +34 MouseY (WORD)
 *  +36  Seconds (ULONG)
 *  +40  Micros (ULONG)
 *  +44  IDCMPWindow (struct Window *)
 *  +48  SpecialLink (struct IntuiMessage *)
 */


class IntuiMessage extends Struct {
  /* check-structs: struct IntuiMessage */
  /**
   * Byte offsets of the fields this wrapper touches, named as in
   * intuition/intuition.h. Checked against the compiler's own layout of
   * the struct by scripts/check_structs.py.
   *
   * @type {Object<string, number>}
   */
  static OFFSET = Object.freeze({
    Class:       20,
    Code:        24,
    Qualifier:   26,
    IAddress:    28,
    MouseX:      32,
    MouseY:      34,
    Seconds:     36,
    Micros:      40,
    IDCMPWindow: 44,
  });

  /** @type {number} */
  static SIZE = 52;

  /**
   * REPL help text — a human-readable constructor signature.
   *
   * @returns {string}
   */
  static get signature() {
    return `IntuiMessage(ptr?)
where:
  ptr? - optional existing struct IntuiMessage pointer to wrap.
         Intuition allocates these and delivers them to a Window's
         UserPort; most code gets them from the win.messages()
         iterator rather than constructing.

Fields (read-only getters):
  class       {CEnumeration|number}  IDCMP_* flag at +20, resolved
                                     via Intuition.consts.fromPrefix('IDCMP_', raw)
  classRaw    {number}               raw ULONG at +20
  code        {number}               UWORD event code, +24
  qualifier   {number}               UWORD shift/alt/ctrl bits, +26
  iAddress    {number}               APTR of source gadget/etc, +28
  mouseX      {number}               WORD, +32
  mouseY      {number}               WORD, +34
  seconds     {number}               ULONG event secs, +36
  micros      {number}               ULONG event micros, +40
  idcmpWindow {number}               source Window ptr, +44

Methods:
  reply()  - ReplyMsg(this) back to Intuition.

Typical use:
  for (let msg of win.messages()) {
    if (msg.class === Intuition.consts.IDCMP_CLOSEWINDOW) break;
  }`;
  }

  /**
   * The IDCMP_* class flag for this message. Returns the matching
   * CEnumeration case from `Intuition.consts` so `===` works:
   *
   *   if (msg.class === Intuition.consts.IDCMP_CLOSEWINDOW) { ... }
   *
   * Falls back to the raw number if no case matches (unknown flag).
   * The case still coerces to its numeric value in bitwise and
   * arithmetic contexts, so `msg.class | 0`, `msg.class & MASK`, and
   * `Number(msg.class)` all give the raw flag.
   *
   * @returns {CEnumeration|number}
   */
  get class() {
    let raw = this.read32(IntuiMessage.OFFSET.Class);
    let Intuition = globalThis.amiga && globalThis.amiga.Intuition;

    if (Intuition && Intuition.consts && Intuition.consts.fromPrefix) {
      /* By family, not by value alone: 0x200 is IDCMP_CLOSEWINDOW here,
       * but it is also WFLG_REPORTMOUSE and other constants. */
      let hit = Intuition.consts.fromPrefix('IDCMP_', raw);

      if (hit) {
        return hit;
      }
    }

    return raw;
  }

  /**
   * Reinterpret an unsigned 16-bit read as a signed WORD. MouseX and
   * MouseY are WORDs: left of or above the window they are negative,
   * and read unsigned they came out near 65535 (until 0.213).
   *
   * @param {number} value - 0..65535
   * @returns {number} -32768..32767
   */
  static _signed16(value) {
    return value > 32767 ? value - 65536 : value;
  }

  /** @returns {number} same as `class` but always the raw flag */
  get classRaw() { return this.read32(IntuiMessage.OFFSET.Class); }

  /** @returns {number} */
  get code()      { return this.read16(IntuiMessage.OFFSET.Code); }

  /** @returns {number} */
  get qualifier() { return this.read16(IntuiMessage.OFFSET.Qualifier); }

  /** @returns {number} */
  get iAddress()  { return this.read32(IntuiMessage.OFFSET.IAddress); }

  /** @returns {number} */
  get mouseX()    { return IntuiMessage._signed16(this.read16(IntuiMessage.OFFSET.MouseX)); }

  /** @returns {number} */
  get mouseY()    { return IntuiMessage._signed16(this.read16(IntuiMessage.OFFSET.MouseY)); }

  /** @returns {number} */
  get seconds()   { return this.read32(IntuiMessage.OFFSET.Seconds); }

  /** @returns {number} */
  get micros()    { return this.read32(IntuiMessage.OFFSET.Micros); }

  /** @returns {number} */
  get idcmpWindow() { return this.read32(IntuiMessage.OFFSET.IDCMPWindow); }

  /**
   * Reply this message back to Intuition. After calling, the message
   * memory is no longer ours to read.
   *
   * @returns {undefined}
   */
  reply() {
    /* Late-bound to avoid circular import — Exec is loaded before us. */
    globalThis.amiga.Exec.ReplyMsg(this);
  }
}


/* === structs/TextAttr.js === */
/* quickjs-master/amiga/ffi/structs/TextAttr.js
 *
 * struct TextAttr (graphics/text.h):
 *   +0  ta_Name   (STRPTR, 4)
 *   +4  ta_YSize  (UWORD, 2)
 *   +6  ta_Style  (UBYTE, 1)
 *   +7  ta_Flags  (UBYTE, 1)
 *  total 8
 */


class TextAttr extends Struct {
  /* check-structs: struct TextAttr */
  /**
   * Byte offsets of the fields this wrapper touches, named as in
   * graphics/text.h. Checked against the compiler's own layout of
   * the struct by scripts/check_structs.py.
   *
   * @type {Object<string, number>}
   */
  static OFFSET = Object.freeze({
    ta_Name:  0,
    ta_YSize: 4,
    ta_Style: 6,
    ta_Flags: 7,
  });

  /** @type {number} */
  static SIZE = 8;

  /**
   * REPL help text — a human-readable constructor signature.
   *
   * @returns {string}
   */
  static get signature() {
    return `TextAttr(ptr?)
where:
  ptr? - optional existing struct TextAttr pointer to wrap (no
         allocation, no ownership). Omit to allocate a fresh 8-byte
         struct filled with zeroes (free() when done).

Fields:
  name     {string|null}  font name at +0, read as a string
  namePtr  {number}       the same field as a pointer; settable
  ySize    {number}       font height in pixels, +4; settable
  style    {number}       Graphics.consts.FSF_* bits, +6; settable
  flags    {number}       Graphics.consts.FPF_* bits, +7; settable

To describe a font of your own, allocate the name and point at it:
  let name = amiga.allocString('topaz.font');
  let attr = new TextAttr();
  attr.namePtr = name.ptr;      // the string must outlive the TextAttr
  attr.ySize   = 8;
  attr.style   = Graphics.consts.FS_NORMAL;
  ...
  attr.free(); name.free();

Typical use:
  screen.font.name, screen.font.ySize — live view of the screen's
  font TextAttr. Do NOT write to system-owned instances.`;
  }

  /** @returns {string|null} font name */
  get name() {
    let p = this.read32(TextAttr.OFFSET.ta_Name);

    return p ? globalThis.amiga.peekString(p, 64) : null;
  }

  /** @returns {number} the font name as a C string pointer (ta_Name) */
  get namePtr()  { return this.read32(TextAttr.OFFSET.ta_Name); }
  set namePtr(v) { this.write32(TextAttr.OFFSET.ta_Name, (v && v.ptr) || (v | 0)); }

  /** @returns {number} font height in pixels */
  get ySize()  { return this.read16(TextAttr.OFFSET.ta_YSize); }
  set ySize(v) { this.write16(TextAttr.OFFSET.ta_YSize, v | 0); }

  /** @returns {number} Graphics.consts.FS_NORMAL or FSF_* bits */
  get style()  { return this.read8(TextAttr.OFFSET.ta_Style); }
  set style(v) { this.write8(TextAttr.OFFSET.ta_Style, v | 0); }

  /** @returns {number} Graphics.consts.FPF_* bits */
  get flags()  { return this.read8(TextAttr.OFFSET.ta_Flags); }
  set flags(v) { this.write8(TextAttr.OFFSET.ta_Flags, v | 0); }
}


