/* === structs/RastPort.js === */
/* quickjs-master/amiga/ffi/structs/RastPort.js
 *
 * Wraps a struct RastPort pointer. Exposes drawing methods that
 * delegate to Graphics.* — instances are typically obtained via
 * Window.rastPort, never allocated by user code.
 */


class RastPort extends Struct {
  /* check-structs: struct RastPort */
  /**
   * Byte offsets of the fields this wrapper touches, named as in
   * graphics/rastport.h. Checked against the compiler's own layout of
   * the struct by scripts/check_structs.py.
   *
   * @type {Object<string, number>}
   */
  static OFFSET = Object.freeze({
    TxHeight:   58,
    TxBaseline: 62,
  });

  /** sizeof(struct RastPort). A window's RastPort belongs to
   *  Intuition; this is for a RastPort of your own (see scratch()).
   *  @type {number} */
  static SIZE = 100;

  /**
   * Make a RastPort that is not attached to anything, for measuring
   * text before a window exists, or in a font other than the screen's:
   *
   *   let measure = RastPort.scratch(font);
   *   let width   = measure.textWidth('Hello');
   *   let height  = measure.fontHeight;
   *   measure.free();
   *
   * It has no bitmap, so it cannot be drawn into; textWidth,
   * fontHeight and fontBaseline are what it is for. free() it when
   * done.
   *
   * @param {number} [font] - struct TextFont pointer to measure in
   * @returns {RastPort} an owned RastPort; call free()
   */
  static scratch(font) {
    let rastPort = new RastPort();

    globalThis.amiga.Graphics.InitRastPort(rastPort);
    if (font) globalThis.amiga.Graphics.SetFont(rastPort, font);

    return rastPort;
  }

  /**
   * REPL help text — a human-readable constructor signature.
   *
   * @returns {string}
   */
  static get signature() {
    return `RastPort(ptr)
where:
  ptr - an existing struct RastPort pointer, typically win.rastPort
        from a Window wrapper. For a RastPort of your own, to measure
        text with, use RastPort.scratch(font).

Instance methods (delegate to graphics.library):
  setColor(pen)              - SetAPen
  setBgColor(pen)            - SetBPen
  move(x, y)                 - Move (no drawing)
  draw(x, y)                 - Draw line from cursor to (x,y)
  rectFill(x1, y1, x2, y2)   - RectFill with A-pen
  text(x, y, str)            - Move + render JS string (allocates
                               and frees C-string internally)
  textWidth(str)             - pixel width of str in the current font

Properties (read-only, graphics/rastport.h):
  fontHeight    {number} rp_TxHeight, +58: pixels in one line of text
  fontBaseline  {number} rp_TxBaseline, +62: top of a line to its
                         baseline; text(x, y) puts the BASELINE at y`;
  }

  /** @returns {number} height in pixels of the current font */
  get fontHeight()   { return this.read16(RastPort.OFFSET.TxHeight); }

  /** @returns {number} pixels from the top of a line to its baseline */
  get fontBaseline() { return this.read16(RastPort.OFFSET.TxBaseline); }

  /**
   * The width of a piece of text in this RastPort's current font.
   *
   * @param {string} str - plain ASCII / Latin-1
   * @returns {number} pixels
   */
  textWidth(str) {
    str = String(str);
    if (str.length === 0) return 0;

    return globalThis.amiga.withString(str, (pointer) =>
      globalThis.amiga.Graphics.TextLength(this, pointer, str.length));
  }

  /**
   * Set foreground pen.
   *
   * @param {number} pen
   * @returns {undefined}
   */
  setColor(pen) {
    globalThis.amiga.Graphics.SetAPen(this, pen);
  }

  /**
   * Set background pen.
   *
   * @param {number} pen
   */
  setBgColor(pen) {
    globalThis.amiga.Graphics.SetBPen(this, pen);
  }

  /**
   * Position the graphics cursor.
   *
   * @param {number} x
   * @param {number} y
   */
  move(x, y) {
    globalThis.amiga.Graphics.Move(this, x, y);
  }

  /**
   * Draw a line from the cursor to (x,y).
   *
   * @param {number} x
   * @param {number} y
   */
  draw(x, y) {
    globalThis.amiga.Graphics.Draw(this, x, y);
  }

  /**
   * Draw a filled rectangle.
   *
   * @param {number} x1
   * @param {number} y1
   * @param {number} x2
   * @param {number} y2
   */
  rectFill(x1, y1, x2, y2) {
    globalThis.amiga.Graphics.RectFill(this, x1, y1, x2, y2);
  }

  /**
   * Move + render a string. Allocates + frees the C string internally.
   *
   * @param {number} x
   * @param {number} y
   * @param {string} str
   */
  text(x, y, str) {
    str = String(str);

    globalThis.amiga.withString(str, (pointer) => {
      this.move(x, y);
      globalThis.amiga.Graphics.Text(this, pointer, str.length);
    });
  }
}


/* === structs/DrawInfo.js === */
/* quickjs-master/amiga/ffi/structs/DrawInfo.js
 *
 * struct DrawInfo (intuition/screens.h). Read-only descriptor handed
 * to BOOPSI images (via SYSIA_DrawInfo / IA_DrawInfo) so they can
 * render using the correct pens and system font.
 *
 * Field offsets (2-byte alignment):
 *   +0   dri_Version    (UWORD)
 *   +2   dri_NumPens    (UWORD)
 *   +4   dri_Pens       (UWORD *)
 *   +8   dri_Font       (struct TextFont *)
 *  +12   dri_Depth      (UWORD)
 *  +14   dri_Resolution (struct {UWORD X; UWORD Y;})  → 4 bytes
 *  +18   dri_Flags      (ULONG)
 *  +22   dri_CheckMark  (struct Image *)    — 3.2R4
 *  +26   dri_AmigaKey   (struct Image *)    — 3.2R4
 *   ...reserved / private follows
 *
 * Obtained via Intuition.GetScreenDrawInfo(screen) and released
 * with Intuition.FreeScreenDrawInfo(screen, dri) — neither is
 * wrapped yet, so use raw amiga.call for now.
 */


class DrawInfo extends Struct {
  /* check-structs: struct DrawInfo */
  /**
   * Byte offsets of the fields this wrapper touches, named as in
   * intuition/screens.h. Checked against the compiler's own layout of
   * the struct by scripts/check_structs.py.
   *
   * @type {Object<string, number>}
   */
  static OFFSET = Object.freeze({
    dri_Version: 0,
    dri_NumPens: 2,
    dri_Pens:    4,
    dri_Font:    8,
    dri_Depth:   12,
    resolutionX: 14,   /* dri_Resolution + 0 as 2 bytes: its X */
    resolutionY: 16,   /* dri_Resolution + 2 as 2 bytes: its Y */
    dri_Flags:   18,
  });

  /* Allocated by Intuition; we wrap. */

  /**
   * REPL help text — human-readable constructor signature.
   *
   * @returns {string}
   */
  static get signature() {
    return `DrawInfo(ptr)
where:
  ptr - REQUIRED: existing struct DrawInfo pointer from
        Intuition.GetScreenDrawInfo(screen). Release with
        Intuition.FreeScreenDrawInfo(screen, dri) when done.

Fields (read-only getters):
  version    {number}  dri_Version, +0
  numPens    {number}  dri_NumPens, +2
  pens       {number}  ptr to UWORD pen array, +4
  font       {number}  TextFont* ptr, +8
  depth      {number}  screen depth, +12
  resolutionX {number} +14 (UWORD)
  resolutionY {number} +16 (UWORD)
  flags      {number}  dri_Flags, +18
  checkMark  {Image|null} CheckMark image, +22 (3.2R4)
  amigaKey   {Image|null} AmigaKey image, +26 (3.2R4)

Typical use (raw-FFI escape hatch, wrapper pending):
  let dri = amiga.call(IntuitionBase,
    amiga.intuition.lvo.GetScreenDrawInfo, { a0: screen.ptr });
  let d = new DrawInfo(dri);
  print(d.numPens + ' pens, depth ' + d.depth);`;
  }

  /** @returns {number} */
  get version()     { return this.read16(DrawInfo.OFFSET.dri_Version); }

  /** @returns {number} */
  get numPens()     { return this.read16(DrawInfo.OFFSET.dri_NumPens); }

  /** @returns {number} UWORD* pen array pointer */
  get pens()        { return this.read32(DrawInfo.OFFSET.dri_Pens); }

  /** @returns {number} TextFont* pointer */
  get font()        { return this.read32(DrawInfo.OFFSET.dri_Font); }

  /** @returns {number} screen depth in bit-planes */
  get depth()       { return this.read16(DrawInfo.OFFSET.dri_Depth); }

  /** @returns {number} horizontal resolution */
  get resolutionX() { return this.read16(DrawInfo.OFFSET.resolutionX); }

  /** @returns {number} vertical resolution */
  get resolutionY() { return this.read16(DrawInfo.OFFSET.resolutionY); }

  /** @returns {number} dri_Flags bitfield */
  get flags()       { return this.read32(DrawInfo.OFFSET.dri_Flags); }

  /**
   * Read one entry from the pen array.
   *
   * @param {number} index — 0..numPens-1
   * @returns {number}  pen number (UWORD)
   */
  getPen(index) {
    let p = this.pens;

    if (!p || index < 0 || index >= this.numPens) return 0;

    return globalThis.amiga.peek16(p + index * 2);
  }
}


/* === structs/Menu.js === */
/* quickjs-master/amiga/ffi/structs/Menu.js
 *
 * struct Menu (intuition/intuition.h). One entry in a window's menu
 * bar; holds a chain of MenuItem via FirstItem.
 *
 * Field offsets (2-byte alignment):
 *   +0   NextMenu   (struct Menu *)
 *   +4   LeftEdge   (WORD)
 *   +6   TopEdge    (WORD)
 *   +8   Width      (WORD)
 *  +10   Height     (WORD)
 *  +12   Flags      (UWORD)
 *  +14   MenuName   (STRPTR)
 *  +18   FirstItem  (struct MenuItem *)
 *  +22   JazzX, JazzY, BeatX, BeatY (UWORD × 4) — runtime layout cache
 *  total 30
 */


class Menu extends Struct {
  /* check-structs: struct Menu */
  /**
   * Byte offsets of the fields this wrapper touches, named as in
   * intuition/intuition.h. Checked against the compiler's own layout of
   * the struct by scripts/check_structs.py.
   *
   * @type {Object<string, number>}
   */
  static OFFSET = Object.freeze({
    NextMenu:  0,
    LeftEdge:  4,
    TopEdge:   6,
    Width:     8,
    Height:    10,
    Flags:     12,
    MenuName:  14,
    FirstItem: 18,
  });

  /** @type {number} */
  static SIZE = 30;

  /**
   * REPL help text.
   *
   * @returns {string}
   */
  static get signature() {
    return `Menu(ptr?)
where:
  ptr? - optional existing struct Menu pointer. Omit to allocate a
         fresh 30-byte struct. Menus are typically built statically
         in C; from JS, use GadTools.CreateMenusA / LayoutMenus via
         the raw-FFI escape hatch until a wrapper lands.

Fields (getters):
  nextMenu   {number} ptr to next Menu in bar, +0
  leftEdge   {number} WORD, +4
  topEdge    {number} WORD, +6
  width      {number} WORD, +8
  height     {number} WORD, +10
  flags      {number} MENUENABLED etc., +12
  menuName   {string|null} menu label, +14 (STRPTR)
  firstItem  {MenuItem|null} first MenuItem in this menu, +18

Setters:
  nextMenu, firstItem, menuName, flags, leftEdge, topEdge,
  width, height (raw numbers/ptrs only).`;
  }

  /** @returns {number} */
  get nextMenu()   { return this.read32(Menu.OFFSET.NextMenu); }
  set nextMenu(v)  { this.write32(Menu.OFFSET.NextMenu, v | 0); }

  /** @returns {number} */
  get leftEdge()   { return this.read16(Menu.OFFSET.LeftEdge); }
  set leftEdge(v)  { this.write16(Menu.OFFSET.LeftEdge, v | 0); }

  /** @returns {number} */
  get topEdge()    { return this.read16(Menu.OFFSET.TopEdge); }
  set topEdge(v)   { this.write16(Menu.OFFSET.TopEdge, v | 0); }

  /** @returns {number} */
  get width()      { return this.read16(Menu.OFFSET.Width); }
  set width(v)     { this.write16(Menu.OFFSET.Width, v | 0); }

  /** @returns {number} */
  get height()     { return this.read16(Menu.OFFSET.Height); }
  set height(v)    { this.write16(Menu.OFFSET.Height, v | 0); }

  /** @returns {number} MENUENABLED = 0x0001 etc. */
  get flags()      { return this.read16(Menu.OFFSET.Flags); }
  set flags(v)     { this.write16(Menu.OFFSET.Flags, v | 0); }

  /** @returns {string|null} */
  get menuName() {
    let p = this.read32(Menu.OFFSET.MenuName);
    return p ? globalThis.amiga.peekString(p, 128) : null;
  }

  /** @param {number} ptr — STRPTR (caller-managed) */
  set menuName(ptr) { this.write32(Menu.OFFSET.MenuName, ptr | 0); }

  /** @returns {MenuItem|null} */
  get firstItem() {
    let p = this.read32(Menu.OFFSET.FirstItem);
    if (!p) return null;

    /* Circular-import-safe lookup through the global namespace. */
    let MI = globalThis.amiga && globalThis.amiga.intuition
          && globalThis.amiga.intuition.MenuItem;

    return MI ? new MI(p) : null;
  }

  set firstItem(v) { this.write32(Menu.OFFSET.FirstItem, (v && v.ptr) || (v | 0)); }
}


