/* === structs/IORequest.js === */
/* quickjs-master/amiga/ffi/structs/IORequest.js
 *
 * struct IORequest (exec/io.h). Base "I/O message" passed to devices
 * via DoIO/SendIO/WaitIO. Size 32 bytes. Concrete devices usually
 * extend this with their own struct (see TimerRequest).
 *
 * Field offsets:
 *   +0   io_Message (struct Message) — 20 bytes
 *  +20   io_Device  (struct Device *)
 *  +24   io_Unit    (struct Unit   *)
 *  +28   io_Command (UWORD)
 *  +30   io_Flags   (UBYTE)
 *  +31   io_Error   (BYTE)
 *  total 32
 *
 * The io_Message header itself has:
 *   +0   mn_Node      (struct Node, 14 bytes)
 *  +14   mn_ReplyPort (struct MsgPort *)
 *  +18   mn_Length    (UWORD)
 */


class IORequest extends Struct {
  /* check-structs: struct IORequest */
  /**
   * Byte offsets of the fields this wrapper touches, named as in
   * exec/io.h. Checked against the compiler's own layout of
   * the struct by scripts/check_structs.py.
   *
   * @type {Object<string, number>}
   */
  static OFFSET = Object.freeze({
    mn_ReplyPort: 14,   /* io_Message.mn_ReplyPort */
    mn_Length:    18,   /* io_Message.mn_Length */
    io_Device:    20,
    io_Unit:      24,
    io_Command:   28,
    io_Flags:     30,
    io_Error:     31,
  });

  /** @type {number} */
  static SIZE = 32;

  /**
   * REPL help text.
   *
   * @returns {string}
   */
  static get signature() {
    return `IORequest(ptr?)
where:
  ptr? - optional existing IORequest* pointer. Omit to allocate 32
         zeroed bytes (caller still needs to fill io_Message's
         mn_ReplyPort, mn_Length, and whatever io_Command/flags the
         target device expects).

Fields:
  replyPort   {number} MsgPort* ptr at +14 (mn_ReplyPort)
  messageLen  {number} UWORD at +18 (mn_Length — struct byte size)
  device      {number} Device* ptr at +20
  unit        {number} Unit* ptr at +24
  command     {number} UWORD at +28
  flags       {number} UBYTE at +30
  error       {number} BYTE at +31

Setters exist for replyPort, messageLen, command, flags, device and
unit. OpenDevice fills in device and unit; set them yourself only to
make a second request for a device that is already open, by copying
both from the first. Never send a request that is still out: use one
request per job. Read 'error' after DoIO.

See TimerRequest for a concrete specialization.`;
  }

  /** @returns {number} */
  get replyPort()   { return this.read32(IORequest.OFFSET.mn_ReplyPort); }
  set replyPort(v)  { this.write32(IORequest.OFFSET.mn_ReplyPort, (v && v.ptr) || (v | 0)); }

  /** @returns {number} */
  get messageLen()  { return this.read16(IORequest.OFFSET.mn_Length); }
  set messageLen(v) { this.write16(IORequest.OFFSET.mn_Length, v | 0); }

  /* device and unit are filled in by OpenDevice. They are writable so
   * that a second request can be pointed at a device that is already
   * open, by copying both from the request that opened it. */

  /** @returns {number} */
  get device()      { return this.read32(IORequest.OFFSET.io_Device); }
  set device(v)     { this.write32(IORequest.OFFSET.io_Device, (v && v.ptr) || (v | 0)); }

  /** @returns {number} */
  get unit()        { return this.read32(IORequest.OFFSET.io_Unit); }
  set unit(v)       { this.write32(IORequest.OFFSET.io_Unit, (v && v.ptr) || (v | 0)); }

  /** @returns {number} */
  get command()     { return this.read16(IORequest.OFFSET.io_Command); }
  set command(v)    { this.write16(IORequest.OFFSET.io_Command, v | 0); }

  /** @returns {number} UBYTE */
  get flags()       { return this.read8(IORequest.OFFSET.io_Flags); }
  set flags(v)      { this.write8(IORequest.OFFSET.io_Flags, v | 0); }

  /** @returns {number} BYTE (may be negative for error codes) */
  get error()       {
    let b = this.read8(IORequest.OFFSET.io_Error);
    /* BYTE is signed; extend from 8-bit 2s-complement. */
    return b >= 0x80 ? b - 0x100 : b;
  }
}


/* === structs/TimerRequest.js === */
/* quickjs-master/amiga/ffi/structs/TimerRequest.js
 *
 * struct timerequest (devices/timer.h). IORequest + one timeval,
 * used by timer.device for delays.
 *
 * Field offsets (continues IORequest, 2-byte aligned):
 *   +0..31  IORequest header (see IORequest.js)
 *  +32      tv_secs   (ULONG)
 *  +36      tv_micro  (ULONG)
 *  total 40
 *
 * Units: UNIT_MICROHZ (0) = µs precision; UNIT_VBLANK (1) = VBL ticks.
 * Commands: TR_ADDREQUEST (9) = "signal me after tv_secs.tv_micro",
 *           TR_GETSYSTIME (10) = "fill tv with the system time".
 *           (11 is TR_SETSYSTIME, which SETS the clock. This file said
 *           11 for GETSYSTIME until 0.213.)
 */


class TimerRequest extends IORequest {
  /* check-structs: struct timerequest */
  /**
   * Byte offsets of the fields this wrapper touches, named as in
   * devices/timer.h. Checked against the compiler's own layout of
   * the struct by scripts/check_structs.py.
   *
   * @type {Object<string, number>}
   */
  static OFFSET = Object.freeze({
    tv_secs:  32,   /* tr_time.tv_secs */
    tv_micro: 36,   /* tr_time.tv_micro */
  });

  /** @type {number} */
  static SIZE = 40;

  /**
   * timer.device units and commands (devices/timer.h). Cases coerce to
   * their numeric value, so they can be given straight to
   * Exec.OpenDevice and to the `command` setter.
   *
   * The commands are written as the header writes them: counted up
   * from CMD_NONSTD, which exec/io.h defines as 9.
   *
   * @example
   * const T = TimerRequest.consts;
   * Exec.OpenDevice('timer.device', T.UNIT_VBLANK, request, 0);
   * request.command = T.TR_ADDREQUEST;
   */
  static consts = CEnumeration.lazy('TimerConsts', {
    /* consts-begin - written by scripts/gen_consts.py from the NDK headers; do not edit */
    /* Units: the second argument of OpenDevice (devices/timer.h) */
    UNIT_MICROHZ:    0,
    UNIT_VBLANK:     1,
    UNIT_ECLOCK:     2,
    UNIT_WAITUNTIL:  3,
    UNIT_WAITECLOCK: 4,

    /* Commands: TimerRequest.command (devices/timer.h) */
    TR_ADDREQUEST: 9,   /* CMD_NONSTD */
    TR_GETSYSTIME: 10,   /* CMD_NONSTD + 1 */
    TR_SETSYSTIME: 11,   /* CMD_NONSTD + 2 */
    /* consts-end */
  });

  /**
   * REPL help text.
   *
   * @returns {string}
   */
  static get signature() {
    return `TimerRequest(ptr?)
where:
  ptr? - optional existing struct timerequest pointer. Omit to
         allocate a zeroed 40-byte TimerRequest.

Fields (inherits IORequest + adds):
  tvSecs   {number} tv_secs,  +32 (ULONG)
  tvMicro  {number} tv_micro, +36 (ULONG)
  setTimeval(secs, micro)     convenience setter

Typical use:
  // open timer.device first (not wrapped yet — use raw FFI).
  let tr = new TimerRequest();
  tr.replyPort  = port.ptr;
  tr.messageLen = TimerRequest.SIZE;
  tr.command = 9;            // TR_ADDREQUEST
  tr.setTimeval(2, 0);       // 2 seconds
  // then Exec.DoIO(tr) or SendIO.

Commands:
  TR_ADDREQUEST = 9
  TR_GETSYSTIME = 10
  TR_SETSYSTIME = 11   (sets the clock; not a read)
  CMD_ABORTIO   = 4`;
  }

  /** @returns {number} ULONG seconds */
  get tvSecs()   { return this.read32(TimerRequest.OFFSET.tv_secs); }
  set tvSecs(v)  { this.write32(TimerRequest.OFFSET.tv_secs, v | 0); }

  /** @returns {number} ULONG microseconds (0..999999) */
  get tvMicro()  { return this.read32(TimerRequest.OFFSET.tv_micro); }
  set tvMicro(v) { this.write32(TimerRequest.OFFSET.tv_micro, v | 0); }

  /**
   * Fill both tv fields at once.
   *
   * @param {number} secs  — seconds
   * @param {number} micro — microseconds (0..999999)
   * @returns {undefined}
   */
  setTimeval(secs, micro) {
    this.tvSecs  = secs;
    this.tvMicro = micro;
  }
}


