    ASLFR_GetSortDrawers:     0x8008007F,   /* ASL_TB + 127 */
    ASLFR_SetSortOrder:       0x80080080,   /* ASL_TB + 128 */
    ASLFR_GetSortOrder:       0x80080081,   /* ASL_TB + 129 */

